components.css:
.ds-tile { aspect-ratio: 1 / 1; background: #f5edd8; border: 1px solid #d6c9b1; padding: 8px; display: flex; flex-direction: column; justify-content: space-between; position: relative; border-left: 3px solid #4a7c59; }
.ds-tile-lv2 { background: #f5edd8; border-left-color: #4a7c59; }
.ds-tile-lv3 { background: #fad2a0; border-left-color: #b85c38; }
.ds-tile-lv1 { background: #f5edd8; border-left-color: #4a7c59; }
.ds-tile-lv0 { background: #ece8dc; border-left-color: #6b5e4f; }
.ds-tile .ds-tile-id { font-family: "Bricolage Grotesque", sans-serif; font-size: 11px; color: #6b5e4f; }
.ds-tile .ds-tile-nome { font-size: 12px; line-height: 1.3; display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.ds-tile .ds-tile-preco { font-family: "Bricolage Grotesque", sans-serif; font-weight: 700; font-size: 13px; }
.ds-tile .ds-tile-badge { position: absolute; top: 4px; right: 4px; width: 22px; height: 22px; background: #2a2218; color: #fff; display: flex; align-items: center; justify-content: center; font-family: "Bricolage Grotesque", sans-serif; font-size: 12px; font-weight: 700; }

.ds-card { background: #fffef5; border: 1px solid #d6c9b1; padding: 18px; box-shadow: 4px 4px 0 rgba(42,34,24,0.08); }
.ds-card-titulo { font-family: "Bricolage Grotesque", sans-serif; text-transform: uppercase; letter-spacing: 0.08em; font-size: 13px; color: #6b5e4f; margin-bottom: 6px; }
.ds-card-num { font-family: "Bricolage Grotesque", sans-serif; font-size: 34px; font-weight: 700; }
.ds-card-sub { font-size: 13px; color: #6b5e4f; }

.ds-column-wrapper { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-top: 24px; }
.ds-coluna { background: #fffef5; border: 1px solid #d6c9b1; padding: 16px; box-shadow: 4px 4px 0 rgba(42,34,24,0.08); }
.ds-coluna-header { font-family: "Bricolage Grotesque", sans-serif; text-transform: uppercase; letter-spacing: 0.08em; font-size: 13px; color: #6b5e4f; margin-bottom: 12px; padding-bottom: 8px; border-bottom: 1px solid #d6c9b1; }
.ds-coluna-sub { font-size: 12px; color: #6b5e4f; margin-top: 2px; }
.ds-coluna-legend { display: flex; flex-wrap: wrap; gap: 10px; margin-bottom: 10px; font-size: 11px; color: #6b5e4f; text-transform: uppercase; letter-spacing: 0.08em; }
.ds-legend-item { display: inline-flex; align-items: center; gap: 6px; }
.ds-legend-swatch { display: inline-block; width: 10px; height: 10px; border: 1px solid #d6c9b1; }
.ds-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(110px, 1fr)); gap: 10px; }

.ds-catalog-sidebar { position: fixed; top: 0; left: 0; width: 260px; height: 100vh; background: #fdf6e3; border-right: 2px solid #d6c9b1; overflow-y: auto; z-index: 100; padding: 16px; }
.ds-catalog-sidebar-header { margin-bottom: 12px; padding-bottom: 8px; border-bottom: 1px solid #d6c9b1; }
.ds-catalog-sidebar-title { font-family: "Bricolage Grotesque", sans-serif; text-transform: uppercase; letter-spacing: 0.08em; font-size: 13px; color: #6b5e4f; }
.ds-catalog-sidebar-sub { font-size: 12px; color: #6b5e4f; margin-top: 2px; }
.ds-categoria-group { margin-bottom: 14px; }
.ds-categoria-title { font-family: "Bricolage Grotesque", sans-serif; text-transform: uppercase; letter-spacing: 0.08em; font-size: 10px; color: #6b5e4f; margin-bottom: 6px; border-bottom: 1px dashed #d6c9b1; padding-bottom: 3px; }
.ds-catalog-sidebar .ds-grid { grid-template-columns: repeat(auto-fill, minmax(80px, 1fr)); gap: 6px; }
.ds-tile-small { background: #e8e3d6; border: 1px solid #d6c9b1; padding: 6px; font-size: 10px; }
.ds-tile-small-id { font-size: 9px; color: #6b5e4f; }
.ds-tile-small-nome { font-size: 10px; -webkit-line-clamp: 2; overflow: hidden; }
.ds-tile-small-preco { font-size: 10px; font-weight: 700; }
